// 프로젝트가 복사해 소유하는 인증 코드 입력·남은 시간·만료·재전송 화면이다.
import { useId, useState } from 'react';
import { isAuthCode, type useAuthChallenge } from '@boosterlab/web-kit/auth';

export interface AuthCodeFormProps {
  readonly model: ReturnType<typeof useAuthChallenge>;
  readonly codeLength: number;
  readonly labels: { readonly code: string; readonly confirm: string; readonly resend: string;
    readonly expired: string; readonly pending: string; readonly failure: string; readonly invalidCode: string;
    readonly remaining: (seconds: number) => string; readonly resendWait: (seconds: number) => string };
}

/** 기한 판정과 제출은 패키지 모델에 연결하고, 입력 모양·문구는 복사본이 맡는다. */
export function AuthCodeForm({ model, codeLength, labels }: AuthCodeFormProps) {
  const [code, setCode] = useState('');
  const [invalid, setInvalid] = useState(false);
  const errorId = useId();
  return <form onSubmit={(event) => { event.preventDefault();
    if (!model.canSubmit) return;
    const valid = isAuthCode(code, codeLength);
    setInvalid(!valid);
    if (valid) void model.submit(code); }}>
    <label>{labels.code}<input aria-label={labels.code} aria-invalid={invalid} aria-describedby={invalid ? errorId : undefined} inputMode="numeric" autoComplete="one-time-code"
      maxLength={codeLength} value={code} onChange={(event) => setCode(event.target.value)} /></label>
    {invalid && <p id={errorId} role="alert">{labels.invalidCode}</p>}
    {model.remainingSeconds !== undefined && <p role="timer">{labels.remaining(model.remainingSeconds)}</p>}
    {(model.expired || model.codeExpired) && <p role="alert">{labels.expired}</p>}
    {model.failure !== undefined && <p role="alert">{labels.failure}</p>}
    {model.pending !== null && <p role="status">{labels.pending}</p>}
    <button type="submit" disabled={!model.canSubmit}>{labels.confirm}</button>
    <button type="button" disabled={!model.canResend} onClick={() => { void model.resend(); }}>{labels.resend}</button>
    {model.resendRemainingSeconds > 0 && <p aria-label="resend-wait">{labels.resendWait(model.resendRemainingSeconds)}</p>}
  </form>;
}

// 검사 전용 여섯 칸 복사본으로, 같은 인증 동작을 독립된 입력 모양에 연결한다.
import { useId, useState } from 'react';
import { isAuthCode } from '@boosterlab/web-kit/auth';
import type { AuthConformanceFormProps as AuthCodeFormProps } from '@boosterlab/web-kit/testing/fixtures';

/** 기한 판정과 제출은 패키지 모델에 연결하고, 입력 모양·문구는 복사본이 맡는다. */
export function SixDigitAuthCodeForm({ model, codeLength, labels }: AuthCodeFormProps) {
  const [code, setCode] = useState('');
  const [invalid, setInvalid] = useState(false);
  const errorId = useId();
  return <form onSubmit={(event) => { event.preventDefault();
    if (!model.canSubmit) return;
    const valid = isAuthCode(code, codeLength);
    setInvalid(!valid);
    if (valid) void model.submit(code); }}>
    <fieldset><legend>{labels.code}</legend>{Array.from({ length: codeLength }, (_, index) =>
      <input key={index} aria-label={`${labels.code} ${index + 1}`} aria-invalid={invalid} aria-describedby={invalid ? errorId : undefined} inputMode="numeric" maxLength={1}
        value={code[index] ?? ''} onChange={(event) => {
          const next = Array.from({ length: codeLength }, (_, digit) => code[digit] ?? ' ');
          next[index] = event.target.value || ' ';
          setCode(next.join(''));
        }} />)}</fieldset>
    {invalid && <p id={errorId} role="alert">{labels.invalidCode}</p>}
    {model.remainingSeconds !== undefined && <p role="timer">{labels.remaining(model.remainingSeconds)}</p>}
    {(model.expired || model.codeExpired) && <p role="alert">{labels.expired}</p>}
    {model.failure !== undefined && <p role="alert">{labels.failure}</p>}
    {model.pending !== null && <p role="status">{labels.pending}</p>}
    <button type="submit" disabled={!model.canSubmit}>{labels.confirm}</button>
    <button type="button" disabled={!model.canResend} onClick={() => { void model.resend(); }}>{labels.resend}</button>
    {model.resendRemainingSeconds > 0 && <p aria-label="resend-wait">{labels.resendWait(model.resendRemainingSeconds)}</p>}
  </form>;
}

// @vitest-environment jsdom
// 복사본 두 모양의 입력 행동을 공통 적합성 검사에 연결한다.
import { describe } from 'vitest';
import { fireEvent, screen } from '@testing-library/react';
import { checkAuthConformance } from '@boosterlab/web-kit/testing/unit';
import { AuthCodeForm } from '../auth';
import { SixDigitAuthCodeForm } from './auth-six';
import installation from '../../../../../registry-installation.json';
const target = { registryVersion: installation.sourceRef, registryCommit: installation.sourceCommit };
describe('한 칸', () => checkAuthConformance({ Form: AuthCodeForm,
  enterCode: (code) => fireEvent.change(screen.getByRole('textbox', { name: '코드' }), { target: { value: code } }),
  readCode: () => (screen.getByRole('textbox', { name: '코드' }) as HTMLInputElement).value,
}, target));
describe('여섯 칸', () => checkAuthConformance({ Form: SixDigitAuthCodeForm,
  enterCode: (code) => Array.from(code).forEach((digit, index) => fireEvent.change(screen.getByRole('textbox', { name: `코드 ${index + 1}` }), { target: { value: digit } })),
  readCode: () => Array.from({ length: 6 }, (_, index) => (screen.getByRole('textbox', { name: `코드 ${index + 1}` }) as HTMLInputElement).value).join(''),
}, target));

// 설치된 두 인증 복사본을 실제 브라우저 검사 화면에 연결한다.
import { createRoot } from 'react-dom/client';
import { createAuthConformancePage } from '@boosterlab/web-kit/testing/fixtures';
import { AuthCodeForm } from '../auth';
import { SixDigitAuthCodeForm } from './auth-six';
const Page = createAuthConformancePage(new URLSearchParams(location.search).has('six') ? SixDigitAuthCodeForm : AuthCodeForm);
createRoot(document.getElementById('root')!).render(<Page />);

// 브라우저에서 실제 입력·Enter 행동을 두 복사본에 연결한다.
import { test } from '@playwright/test';
import { checkAuthBrowser } from '@boosterlab/web-kit/testing/browser';
import installation from '../../../registry-installation.json' with { type: 'json' };
const target = { registryVersion: installation.sourceRef, registryCommit: installation.sourceCommit };
test.describe('한 칸', () => checkAuthBrowser({ url: '/web-kit-checks/auth.html', target,
  enterCode: async (page, code) => { await page.getByRole('textbox', { name: '코드', exact: true }).fill(code); },
  readCode: async (page) => page.getByRole('textbox', { name: '코드', exact: true }).inputValue(),
}));
test.describe('여섯 칸', () => checkAuthBrowser({ url: '/web-kit-checks/auth.html?six', target,
  enterCode: async (page, code) => { for (let i = 0; i < code.length; i++) await page.getByRole('textbox', { name: `코드 ${i + 1}`, exact: true }).fill(code[i]!); },
  readCode: async (page) => { const digits = []; for (let i = 0; i < 6; i++) digits.push(await page.getByRole('textbox', { name: `코드 ${i + 1}`, exact: true }).inputValue()); return digits.join(''); },
}));
